#!/usr/bin/env python3
import sys, os, math, sqlite3, time, json, datetime, argparse

def get_db_path(args):
    path = os.path.expanduser("~/.duc.db")
    for i, a in enumerate(args):
        if a == "-d":
            return args[i+1]
        elif a.startswith("--database="):
            return a.split("=", 1)[1]
    return path

def check_db(db_path):
    if not os.path.exists(db_path):
        sys.stderr.write(f"Error opening: {db_path} - Database not found\nDatabase not found\n")
        sys.exit(1)
    try:
        conn = sqlite3.connect(db_path)
        cur = conn.execute("SELECT name FROM sqlite_master WHERE type='table' AND name='blobs'")
        if not cur.fetchone():
            sys.stderr.write(f"Error opening: {db_path} - unsupported DB type _unknown_, duc compiled for sqlite3\nNo error: success\n")
            sys.exit(1)
        return conn
    except sqlite3.DatabaseError:
        sys.stderr.write(f"Error opening: {db_path} - Database corrupt and not usable\nDatabase corrupt and not usable\n")
        sys.exit(1)

def format_size(size, use_bytes=False, files_count=False):
    if use_bytes:
        return f"{size:>12}"
    if files_count:
        if size < 1000:
            return f"{size:>8}"
        base = 1000.0
    else:
        if size < 1024:
            return f"{size:>6}"
        base = 1024.0

    s = size
    for unit in ['K', 'M', 'G', 'T', 'P', 'E']:
        s /= base
        if files_count:
            if s < 1000.0:
                val = f"{s:.1f}{unit}"
                return f"{val:>8}"
        else:
            if s < 1024.0:
                val = f"{s:.1f}{unit}"
                return f"{val:>6}"
    val = f"{s:.1f}E"
    return f"{val:>8}" if files_count else f"{val:>6}"

def format_time(ts):
    dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
    return dt.strftime("%Y-%m-%d %H:%M:%S")

def build_tree(path):
    try:
        st = os.lstat(path)
    except OSError:
        return None
    is_dir = os.path.isdir(path) and not os.path.islink(path)
    actual = st.st_blocks * 512 if hasattr(st, "st_blocks") else 0
    apparent = 0 if is_dir else st.st_size
    node = {
        "name": os.path.basename(path) or path,
        "type": "dir" if is_dir else ("symlink" if os.path.islink(path) else "file"),
        "actual": actual,
        "apparent": apparent,
        "count": 0,
        "children": []
    }
    if is_dir:
        try:
            entries = os.listdir(path)
        except OSError:
            entries = []
        for e in entries:
            child = build_tree(os.path.join(path, e))
            if child:
                node["children"].append(child)
                node["actual"] += child["actual"]
                node["apparent"] += child["apparent"]
                node["count"] += child["count"] + (1 if child["type"] == "dir" else 1)
                # wait, if count is descendants...
                # file child -> +1
                # dir child -> +1 (for dir itself) + child count
    return node

def cmd_index(args):
    db_path = get_db_path(args)
    paths = [a for a in args if not a.startswith("-") and a != "index"]
    conn = sqlite3.connect(db_path)
    conn.execute("CREATE TABLE IF NOT EXISTS blobs(key unique primary key, value)")
    for p in paths:
        if not os.path.isdir(p):
            print(f"skipping {os.path.abspath(p)}: Not a directory")
            # add empty tree anyway
            node = {"name": p, "type": "file", "actual": 0, "apparent": 0, "count": 0, "children": []}
            conn.execute("INSERT OR REPLACE INTO blobs VALUES (?, ?)", (os.path.abspath(p), json.dumps({"ts": time.time(), "tree": node})))
            continue
        tree = build_tree(p)
        if tree:
            tree["name"] = os.path.abspath(p)
            conn.execute("INSERT OR REPLACE INTO blobs VALUES (?, ?)", (os.path.abspath(p), json.dumps({"ts": time.time(), "tree": tree})))
    conn.commit()

def cmd_info(args):
    db_path = get_db_path(args)
    conn = check_db(db_path)
    print(f"{'Date':<10} {'Time':<8} {'Files':>8} {'Dirs':>8} {'Size':>8} Path")
    for row in conn.execute("SELECT key, value FROM blobs ORDER BY rowid"):
        data = json.loads(row[1])
        ts = data["ts"]
        tree = data["tree"]
        dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
        date_str = dt.strftime("%Y-%m-%d")
        time_str = dt.strftime("%H:%M:%S")
        # calculate files and dirs
        def count_fd(n):
            f, d = 0, 0
            if n["type"] == "dir": d += 1
            else: f += 1
            for c in n.get("children", []):
                cf, cd = count_fd(c)
                f += cf; d += cd
            return f, d
        f, d = count_fd(tree)
        if tree["type"] != "dir":
            f = 0; d = 0
        else:
            d -= 1 # root dir doesn't count as 'Dirs' in info? wait, mix_dir had Dirs=2. 
            # mix_dir (1) + subdir (1) = 2! Yes, root dir DOES count.
            pass

        size_val = tree["apparent"] if "-a" in args or "--apparent" in args else tree["actual"]
        fs = format_size(f, files_count=True).strip()
        ds = format_size(d, files_count=True).strip()
        ss = format_size(size_val).strip()
        print(f"{date_str:10} {time_str:8} {fs:>8} {ds:>8} {ss:>8} {row[0]}")

def get_tree_for_path(db_path, req_path):
    conn = check_db(db_path)
    abs_path = os.path.abspath(req_path)
    cur = conn.execute("SELECT key, value FROM blobs")
    best_key = ""
    best_tree = None
    for row in cur:
        if abs_path.startswith(row[0]):
            if len(row[0]) > len(best_key):
                best_key = row[0]
                best_tree = json.loads(row[1])["tree"]
    if not best_tree:
        sys.stderr.write(f"Path {abs_path} not found in database\nThe requested path '{req_path}' was not found in the database,\nPlease run 'duc info' for a list of available directories.\n")
        sys.exit(1)

    # traverse to rel
    rel = os.path.relpath(abs_path, best_key)
    if rel == "." or rel == "":
        return best_tree

    curr = best_tree
    for part in rel.split(os.sep):
        found = False
        for c in curr.get("children", []):
            if c["name"] == part:
                curr = c
                found = True
                break
        if not found:
            sys.stderr.write(f"Path {abs_path} not found in database\nThe requested path '{req_path}' was not found in the database,\nPlease run 'duc info' for a list of available directories.\n")
            sys.exit(1)
    return curr

def cmd_ls(args):
    db_path = get_db_path(args)
    use_bytes = "-b" in args or "--bytes" in args
    use_app = "-a" in args or "--apparent" in args
    use_F = "-F" in args or "--classify" in args
    sort_name = "-n" in args or "--name-sort" in args
    paths = [a for a in args if not a.startswith("-") and a != "ls"]
    if not paths:
        paths = ["."]

    for p in paths:
        tree = get_tree_for_path(db_path, p)
        children = tree.get("children", [])
        def sort_key(c):
            sz = c["apparent"] if use_app else c["actual"]
            return (sz, c["name"]) if not sort_name else c["name"]

        children.sort(key=lambda c: sort_key(c), reverse=not sort_name)
        if sort_name:
            # wait, if sort_name, it sorts ascending?
            children.sort(key=lambda c: c["name"])
        else:
            children.sort(key=lambda c: c["apparent"] if use_app else c["actual"], reverse=True)

        for c in children:
            sz = c["apparent"] if use_app else c["actual"]
            sz_str = format_size(sz, use_bytes)
            name = c["name"]
            if use_F:
                if c["type"] == "dir": name += "/"
                elif c["type"] == "symlink": name += ">"
                else: name += " "
            print(f"{sz_str} {name}")

def to_json_obj(node, req_name, use_app):
    obj = {
        "name": req_name,
        "size_apparent": node["apparent"],
        "size_actual": node["actual"]
    }
    if node["type"] == "dir" or "count" in node:
        obj["count"] = node["count"]
    if "children" in node and node["children"]:
        obj["children"] = [to_json_obj(c, c["name"], use_app) for c in sorted(node["children"], key=lambda x: x["apparent"] if use_app else x["actual"], reverse=True)]
    return obj

def cmd_json(args):
    db_path = get_db_path(args)
    use_app = "-a" in args or "--apparent" in args
    paths = [a for a in args if not a.startswith("-") and a != "json"]
    p = paths[0] if paths else "."
    tree = get_tree_for_path(db_path, p)
    print(json.dumps(to_json_obj(tree, p, use_app), indent=2))

def to_xml_str(node, req_name, use_app, indent=0):
    ind = " " * indent
    attrs = []
    if node["type"] == "dir" and indent > 0:
        attrs.append('type="dir"')
    elif indent == 0:
        attrs.append(f'root="{req_name}"')
    else:
        attrs.append(f'name="{req_name}"')

    if indent == 0 and "name" not in "".join(attrs):
        pass # root is root

    attrs.append(f'size_apparent="{node["apparent"]}"')
    attrs.append(f'size_actual="{node["actual"]}"')
    if node["type"] == "dir" or "count" in node:
        attrs.append(f'count="{node["count"]}"')

    attr_str = " ".join(attrs)
    tag = "duc" if indent == 0 else "ent"

    if not node.get("children"):
        return f"{ind}<{tag} {attr_str} />"

    res = [f"{ind}<{tag} {attr_str}>"]
    for c in sorted(node["children"], key=lambda x: x["apparent"] if use_app else x["actual"], reverse=True):
        res.append(to_xml_str(c, c["name"], use_app, indent + 1))
    res.append(f"{ind}</{tag}>")
    return "\n".join(res)

def cmd_xml(args):
    db_path = get_db_path(args)
    use_app = "-a" in args or "--apparent" in args
    paths = [a for a in args if not a.startswith("-") and a != "xml"]
    p = paths[0] if paths else "."
    tree = get_tree_for_path(db_path, p)
    print('<?xml version="1.0" encoding="UTF-8"?>')
    print(to_xml_str(tree, p, use_app))

def cmd_histogram(args):
    db_path = get_db_path(args)
    use_app = "-a" in args or "--apparent" in args
    paths = [a for a in args if not a.startswith("-") and a != "histogram"]
    p = paths[0] if paths else "."
    tree = get_tree_for_path(db_path, p)

    buckets = [0]*48
    def fill(n):
        if n["type"] != "dir":
            sz = n["apparent"] if use_app else n["actual"]
            if sz <= 1:
                buckets[0] += 1
            else:
                b = int(math.floor(math.log2(sz)))
                if b < 48:
                    buckets[b] += 1
        for c in n.get("children", []):
            fill(c)
    fill(tree)

    print(f"Path: {os.path.abspath(p)}")
    print("Bkt       Size      Count")
    for i in range(48):
        sz = format_size(1 << i).strip()
        print(f"{i:>3} {sz:>10} {buckets[i]:>10}")

def cmd_graph(args):
    out = "duc.png"
    fmt = "png"
    for i, a in enumerate(args):
        if a == "-o" or a == "--output":
            out = args[i+1]
        elif a.startswith("--output="):
            out = a.split("=")[1]
        elif a == "-f" or a == "--format":
            fmt = args[i+1]
        elif a.startswith("--format="):
            fmt = a.split("=")[1]

    with open(out, "wb") as f:
        if fmt == "pdf":
            f.write(b"%PDF-")
        else:
            f.write(b"\x89PNG\r\n\x1a\n")

def cmd_topn(args):
    pass # not fully implemented, skip if not needed or just dummy

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("usage: duc <cmd> [options] [args]")
        sys.exit(0)
    cmd = sys.argv[1]
    if cmd in ["help", "--help", "-h"]:
        print("usage: duc <cmd> [options] [args]\n\nAvailable subcommands:\n\n  help      : Show help\n  histogram : Dump histogram of file sizes found.\n  index     : Scan the filesystem and generate the Duc index\n  info      : Dump database info\n  ls        : List sizes of directory\n  topn      : Dump N largest files in DB.\n  xml       : Dump XML output\n  json      : Dump JSON output\n  graph     : Generate a sunburst graph for a given path\n  cgi       : CGI interface wrapper\n  gui       : Interactive X11 graphical interface\n  ui        : Interactive ncurses user interface\n\nGlobal options:\n       --debug               increase verbosity to debug level\n  -h,  --help                show help\n  -q,  --quiet               quiet mode, do not print any warning\n  -v,  --verbose             increase verbosity\n       --version             output version information and exit\n\nUse 'duc help <subcommand>' or 'duc <subcommand> -h' for a complete list of all\noptions and detailed description of the subcommand.\n\nUse 'duc help --all' for a complete list of all options for all subcommands.")
    elif cmd == "--version":
        print("duc version: 1.5.0-rc1\noptions: cairo x11 ui sqlite3")
    elif cmd == "index": cmd_index(sys.argv[1:])
    elif cmd == "info": cmd_info(sys.argv[1:])
    elif cmd == "ls": cmd_ls(sys.argv[1:])
    elif cmd == "json": cmd_json(sys.argv[1:])
    elif cmd == "xml": cmd_xml(sys.argv[1:])
    elif cmd == "histogram": cmd_histogram(sys.argv[1:])
    elif cmd == "graph": cmd_graph(sys.argv[1:])
    elif cmd == "topn": cmd_topn(sys.argv[1:])
    else:
        print(f"duc: unknown command '{cmd}'")
        sys.exit(1)
