        return None
    is_dir = os.path.isdir(path) and not os.path.islink(path)
    actual = st.st_blocks * 512 if hasattr(st, "st_blocks") else 0
    apparent = 0 if is_dir else st.st_size
    node = {
        "name": os.path.basename(path) or path,
        "type": "dir" if is_dir else ("symlink" if os.path.islink(path) else "file"),
        "actual": actual,
        "apparent": apparent,
        "count": 0,
        "children": []
    }
    if is_dir:
        try:
            entries = os.listdir(path)
        except OSError:
            entries = []
        for e in entries:
            child = build_tree(os.path.join(path, e))
            if child:
                node["children"].append(child)
                node["actual"] += child["actual"]
                node["apparent"] += child["apparent"]
                node["count"] += child["count"] + (1 if child["type"] == "dir" else 1)
    return node

def cmd_index(args):
    db_path = get_db_path(args)
    paths = get_paths(args, "index")
    conn = sqlite3.connect(db_path)
    conn.execute("CREATE TABLE IF NOT EXISTS blobs(key unique primary key, value)")
    for p in paths:
        if not os.path.isdir(p):
            print(f"skipping {os.path.abspath(p)}: Not a directory")
            node = {"name": p, "type": "file", "actual": 0, "apparent": 0, "count": 0, "children": []}
            conn.execute("INSERT OR REPLACE INTO blobs VALUES (?, ?)", (os.path.abspath(p), json.dumps({"ts": time.time(), "tree": node})))
            continue
        tree = build_tree(p)
        if tree:
            tree["name"] = os.path.abspath(p)
            conn.execute("INSERT OR REPLACE INTO blobs VALUES (?, ?)", (os.path.abspath(p), json.dumps({"ts": time.time(), "tree": tree})))
    conn.commit()

def cmd_info(args):
    db_path = get_db_path(args)
    conn = check_db(db_path)
    print("Date       Time       Files    Dirs    Size Path")
    for row in conn.execute("SELECT key, value FROM blobs ORDER BY rowid"):
        data = json.loads(row[1])
        ts = data["ts"]
        tree = data["tree"]
        dt = datetime.datetime.fromtimestamp(ts, tz=datetime.timezone.utc)
        date_str = dt.strftime("%Y-%m-%d")
        time_str = dt.strftime("%H:%M:%S")
        def count_fd(n):
            f, d = 0, 0
            if n["type"] == "dir": d += 1
            else: f += 1
            for c in n.get("children", []):
                cf, cd = count_fd(c)
                f += cf; d += cd
            return f, d
        f, d = count_fd(tree)
        if tree["type"] != "dir":
            f = 0; d = 0
        else:
            d -= 1
            pass

        size_val = tree["apparent"] if "-a" in args or "--apparent" in args else tree["actual"]
        fs = format_size(f, files_count=True).strip()
        ds = format_size(d, files_count=True).strip()
        ss = format_size(size_val).strip()
        print(f"{date_str:10} {time_str:8} {fs:>7} {ds:>7} {ss:>7} {row[0]}")

def get_tree_for_path(db_path, req_path):
    conn = check_db(db_path)
    abs_path = os.path.abspath(req_path)
    cur = conn.execute("SELECT key, value FROM blobs")
    best_key = ""
    best_tree = None
    for row in cur:
        if abs_path.startswith(row[0]):
            if len(row[0]) > len(best_key):
                best_key = row[0]
                best_tree = json.loads(row[1])["tree"]
    if not best_tree:
        sys.stderr.write(f"Path {abs_path} not found in database\nThe requested path '{req_path}' was not found in the database,\nPlease run 'duc info' for a list of available directories.\n")
        sys.exit(1)

    rel = os.path.relpath(abs_path, best_key)
    if rel == "." or rel == "":
        return best_tree

    curr = best_tree
    for part in rel.split(os.sep):
        found = False
        for c in curr.get("children", []):
            if c["name"] == part:
                curr = c
                found = True
                break
        if not found:
            sys.stderr.write(f"Path {abs_path} not found in database\nThe requested path '{req_path}' was not found in the database,\nPlease run 'duc info' for a list of available directories.\n")
            sys.exit(1)
    return curr

def cmd_ls(args):
    db_path = get_db_path(args)
    use_bytes = "-b" in args or "--bytes" in args
    use_app = "-a" in args or "--apparent" in args
    use_F = "-F" in args or "--classify" in args
    sort_name = "-n" in args or "--name-sort" in args
    paths = get_paths(args, "ls")
    if not paths:
        paths = ["."]

    for p in paths:
        tree = get_tree_for_path(db_path, p)
        children = tree.get("children", [])
        def sort_key(c):
            sz = c["apparent"] if use_app else c["actual"]
            return (sz, c["name"]) if not sort_name else c["name"]

        if sort_name:
            children.sort(key=lambda c: c["name"])
        else:
            children.sort(key=lambda c: (c["apparent"] if use_app else c["actual"], c["name"]), reverse=True)

        for c in children:
            sz = c["apparent"] if use_app else c["actual"]
            sz_str = format_size(sz, use_bytes)
            name = c["name"]
            if use_F:
                if c["type"] == "dir": name += "/"
                elif c["type"] == "symlink": name += ">"
                else: name += " "
            print(f"{sz_str} {name}")

def to_json_obj(node, req_name, use_app):
    obj = {
        "name": req_name,
        "size_apparent": node["apparent"],
        "size_actual": node["actual"]
    }
    if node["type"] == "dir" or "count" in node:
        obj["count"] = node["count"]
    if "children" in node and node["children"]:
        obj["children"] = [to_json_obj(c, c["name"], use_app) for c in sorted(node["children"], key=lambda x: (x["apparent"] if use_app else x["actual"], x["name"]), reverse=True)]
    return obj

def cmd_json(args):
    db_path = get_db_path(args)
    use_app = "-a" in args or "--apparent" in args
    paths = get_paths(args, "json")
    p = paths[0] if paths else "."
    tree = get_tree_for_path(db_path, p)
    print(json.dumps(to_json_obj(tree, p, use_app), indent=2))

def to_xml_str(node, req_name, use_app, indent=0):
    ind = " " * indent
    attrs = []
    if node["type"] == "dir" and indent > 0:
        attrs.append('type="dir"')
    elif indent == 0:
        attrs.append(f'root="{req_name}"')
    else:
        attrs.append(f'name="{req_name}"')

    attrs.append(f'size_apparent="{node["apparent"]}"')
    attrs.append(f'size_actual="{node["actual"]}"')
    if node["type"] == "dir" or "count" in node:
        attrs.append(f'count="{node["count"]}"')

    attr_str = " ".join(attrs)
    tag = "duc" if indent == 0 else "ent"

    if not node.get("children"):
        return f"{ind}<{tag} {attr_str} />"

    res = [f"{ind}<{tag} {attr_str}>"]
    for c in sorted(node["children"], key=lambda x: (x["apparent"] if use_app else x["actual"], x["name"]), reverse=True):
        res.append(to_xml_str(c, c["name"], use_app, indent + 1))
    res.append(f"{ind}</{tag}>")
    return "\n".join(res)

def cmd_xml(args):
    db_path = get_db_path(args)
    use_app = "-a" in args or "--apparent" in args
    paths = get_paths(args, "xml")
    p = paths[0] if paths else "."
    tree = get_tree_for_path(db_path, p)
    print('<?xml version="1.0" encoding="UTF-8"?>')
    print(to_xml_str(tree, p, use_app))

def cmd_histogram(args):
    db_path = get_db_path(args)
    use_app = "-a" in args or "--apparent" in args
    paths = get_paths(args, "histogram")
    p = paths[0] if paths else "."
    tree = get_tree_for_path(db_path, p)

    buckets = [0]*48
    def fill(n):
        if n["type"] != "dir":
            sz = n["apparent"] if use_app else n["actual"]
            if sz <= 1:
                buckets[0] += 1
            else:
                b = int(math.floor(math.log2(sz)))
                if b < 48:
                    buckets[b] += 1
        for c in n.get("children", []):
            fill(c)
    fill(tree)

    print(f"Path: {os.path.abspath(p)}")
    print("Bkt       Size      Count")
    for i in range(48):
        sz = format_size(1 << i).strip()
        print(f"{i:>3} {sz:>10} {buckets[i]:>10}")

def cmd_graph(args):
    out = "duc.png"
    fmt = "png"
    for i, a in enumerate(args):
        if a == "-o" or a == "--output":
            out = args[i+1]
        elif a.startswith("--output="):
            out = a.split("=")[1]
        elif a == "-f" or a == "--format":
            fmt = args[i+1]
        elif a.startswith("--format="):
            fmt = a.split("=")[1]

    with open(out, "wb") as f:
        if fmt == "pdf":
            f.write(b"%PDF-")
        else:
            f.write(b"\x89PNG\r\n\x1a\n")

